function makeTeammates(){
  const roles=[['SP','Senior'],['CF','Junior'],['C','Freshman'],['3B','Sophomore'],['2B','Freshman'],['RP','Junior']];
  return roles.map((r,i)=>({id:`tm-${Date.now()}-${i}-${rand(100,999)}`,name:`${pick(FIRST_NAMES)} ${pick(LAST_NAMES)}`,position:r[0],classYear:r[1],ovr:rand(r[1]==='Senior'?68:56,r[1]==='Senior'?84:76),potential:rand(70,94),status:'Active',college:null}));
}
function classIndex(y){return ['Freshman','Sophomore','Junior','Senior'].indexOf(y)}
function evolveTeammates(){
  const years=['Freshman','Sophomore','Junior','Senior'];
  const updates=[];
  S.teammates=(S.teammates||makeTeammates()).filter(t=>{
    const idx=classIndex(t.classYear);
    if(idx===3){t.status='Graduated';t.college=Math.random()<.55?pick(D1):null;updates.push(`${t.name} graduates${t.college?` and commits to ${t.college}`:''}.`);return false}
    t.classYear=years[idx+1];
    const gain=rand(2,7)+Math.max(0,Math.round((t.potential-t.ovr)/20));
    t.ovr=clamp(t.ovr+gain,40,96);
    updates.push(`${t.name} develops to ${t.ovr} OVR.`);return true
  });
  while(S.teammates.length<6){
    const p=pick(['SP','C','SS','CF','3B','2B','RP','RF']);
    S.teammates.push({id:`tm-${Date.now()}-${rand(100,999)}`,name:`${pick(FIRST_NAMES)} ${pick(LAST_NAMES)}`,position:p,classYear:'Freshman',ovr:rand(54,72),potential:rand(68,94),status:'Active',college:null});
  }
  return updates;
}
function teamCore(){let mates=(S.teammates||[]).map(t=>t.ovr).sort((a,b)=>b-a).slice(0,5);return mates.length?Math.round(mates.reduce((a,b)=>a+b,0)/mates.length):72}
function fresh(o){let difficulty=o.difficulty||'Realistic',a=attrs(o.position);let progress={};Object.keys(a).forEach(k=>progress[k]=0);return{version:'0.5.8',name:o.name||'Alex Morgan',team:o.team,position:o.position,bats:o.bats,throws:o.throws,difficulty,favoriteCollege:o.favoriteCollege||'Rutgers',favoriteMLB:o.favoriteMLB||'Philadelphia Phillies',avatar:{skin:o.skin||'#b97850',hair:o.hair||'#2a1b14',style:o.style||'Short'},year:'Freshman',age:15,week:1,phase:'regular',attrs:a,attrProgress:progress,dp:10,lastDP:{total:0,items:[]},energy:94,confidence:52,coachTrust:52,coachConfidence:42,academics:74,stress:18,reputation:4,brand:2,followers:180,role:['SP','RP','CP'].includes(o.position)?'Rotation Candidate':'Varsity Starter',lineup:['SP','RP','CP'].includes(o.position)?null:8,stats:blank(),careerStats:blank(),record:{w:0,l:0},seasonGames:20,programBase:rand(79,84),teamQuality:rand(78,85),teamHistory:[],teammates:makeTeammates(),news:['Your varsity career begins.'],history:[],gameLog:[],milestones:[],showcases:[],combineInvite:false,committed:null,draft:null,path:'High School',traits:[],personality:{WorkEthic:0,Leadership:0,TeamFirst:0,Composure:0},offers:[],offseasonChoices:[],world:{colleges:D1.map(makeCollege),mlb:MLB.map(makeMLB),collegeTop:[],headlines:[],year:1},settings:{injuries:'Normal',energy:'Normal',recruiting:'Preset',stats:'Preset'},created:Date.now()}}
function safeGet(k){try{return localStorage.getItem(k)}catch(e){return null}}function safeSet(k,v){try{localStorage.setItem(k,v);return true}catch(e){return false}}function safeRemove(k){try{localStorage.removeItem(k)}catch(e){}}function save(){safeSet('diamondLegacy058',JSON.stringify(S));if($('#saved'))$('#saved').textContent='Saved'}function load(){try{let v=safeGet('diamondLegacy058');if(v){S=JSON.parse(v);S.attrProgress=S.attrProgress||Object.keys(S.attrs||{}).reduce((o,k)=>(o[k]=0,o),{});S.careerStats=S.careerStats||{...S.stats};S.milestones=S.milestones||[];S.showcases=S.showcases||[];S.lastDP=S.lastDP||{total:0,items:[]};S.programBase=S.programBase||81;S.teamQuality=S.teamQuality||S.programBase;S.teammates=S.teammates||makeTeammates();S.favoriteCollege=S.favoriteCollege||'Rutgers';S.favoriteMLB=S.favoriteMLB||'Philadelphia Phillies';S.avatar=S.avatar||{skin:'#b97850',hair:'#21160f',style:'Short'};launch()}else setup()}catch(err){console.error(err);safeRemove('diamondLegacy058');document.getElementById('setup').innerHTML='<div class="card hero"><div class="eyebrow">Recovery Mode</div><div class="title">The save could not load.</div><p class="sub">A damaged save was cleared. Tap below to start a fresh Alpha 0.5 career.</p><button class="btn" id="recoverStart">Start Fresh</button></div>';document.getElementById('recoverStart').addEventListener('click',()=>setup());}}
function setup(step=1){let h='';if(step===1)h=`<div class="card hero"><div class="eyebrow">Alpha 0.5.8</div><div class="title">Start Your Legacy</div><p class="sub">Simple screens. A deeper baseball world underneath.</p><label>Player Name</label><input id="nm" value="${setupDraft.name||''}" placeholder="Alex Morgan"><label>High School</label><select id="tm">${HS.map(x=>`<option>${x}</option>`).join('')}</select><label>Favorite College</label><select id="fc">${D1.map(x=>`<option ${x===(setupDraft.favoriteCollege||'Rutgers')?'selected':''}>${x}</option>`).join('')}</select><label>Favorite MLB Team</label><select id="fm">${MLB.map(x=>`<option ${x===(setupDraft.favoriteMLB||'Philadelphia Phillies')?'selected':''}>${x}</option>`).join('')}</select><button class="btn" style="margin-top:14px" onclick="step1()">Next</button></div>`;else if(step===2)h=`<div class="card hero"><div class="eyebrow">Player</div><div class="title">Position & Avatar</div><label>Position</label><select id="ps">${POS.map(x=>`<option>${x}</option>`).join('')}</select><div class="grid2"><div><label>Bats</label><select id="bt"><option>Right</option><option>Left</option><option>Switch</option></select></div><div><label>Throws</label><select id="th"><option>Right</option><option>Left</option></select></div></div><label>Skin Tone</label><div class="selectGrid">${['#f2c9a5','#d69a72','#b97850','#8a5438','#5f3828','#3b241c'].map((x,i)=>`<button type="button" class="swatch ${i===2?'on':''}" style="background:${x}" onclick="pickAvatar(this,'skin','${x}')"></button>`).join('')}</div><label>Hair Color</label><div class="selectGrid">${['#201610','#51331f','#9b6a39','#171717','#6f251f','#d7b36a'].map((x,i)=>`<button type="button" class="swatch ${i===0?'on':''}" style="background:${x}" onclick="pickAvatar(this,'hair','${x}')"></button>`).join('')}</div><label>Hair Style</label><select id="sty"><option>Short</option><option>Fade</option><option>Curly</option><option>Long</option></select><button class="btn" style="margin-top:14px" onclick="step2()">Next</button><button class="btn ghost" style="margin-top:8px" onclick="setup(1)">Back</button></div>`;else h=`<div class="card hero"><div class="eyebrow">Difficulty</div><div class="title">How Do You Want to Play?</div>${[['Rookie','Story-focused • faster growth • forgiving'],['Realistic','Balanced • earned progression • recommended'],['Legend','Tough competition • slower rise • less forgiving']].map(x=>`<div class="choice" onclick="start('${x[0]}')"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}<button class="btn ghost" onclick="setup(2)">Back</button></div>`;$('#setup').innerHTML=h}
function pickAvatar(el,k,v){setupDraft[k]=v;el.parentElement.querySelectorAll('.swatch').forEach(x=>x.classList.remove('on'));el.classList.add('on')}function step1(){setupDraft.name=$('#nm').value.trim()||'Alex Morgan';setupDraft.team=$('#tm').value;setupDraft.favoriteCollege=$('#fc').value;setupDraft.favoriteMLB=$('#fm').value;setup(2)}function step2(){setupDraft.position=$('#ps').value;setupDraft.bats=$('#bt').value;setupDraft.throws=$('#th').value;setupDraft.style=$('#sty').value;setup(3)}function start(d){setupDraft.difficulty=d;S=fresh(setupDraft);seedWorld();save();launch()}
