function launch(){$('#setup').classList.add('hidden');$('#game').classList.remove('hidden');$('#nav').classList.remove('hidden');$('#nav').innerHTML=[['home','⌂','Home'],['player','◆','Player'],['recruiting','★','Recruiting'],['world','◎','World'],['history','≡','History']].map((x,i)=>`<button class="${i?'':'on'}" onclick="go('${x[0]}',this)"><b>${x[1]}</b>${x[2]}</button>`).join('');render()}
