function hitPlayer(){return !['SP','RP','CP'].includes(S.position)||S.position==='Two-Way'}function pitchPlayer(){return ['SP','RP','CP','Two-Way'].includes(S.position)}function ovr(){let v=Object.values(S.attrs);return Math.round(v.reduce((a,b)=>a+b,0)/v.length)}function avg(){return S.stats.ab?(S.stats.h/S.stats.ab).toFixed(3).replace(/^0/,''):'.000'}function era(){return S.stats.ip?(S.stats.er*9/S.stats.ip).toFixed(2):'0.00'}function cfg(){return CFG[S.difficulty]}

function initials(n){return n.split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase()}
function hashColor(n){let h=0;for(let c of n)h=(h*31+c.charCodeAt(0))>>>0;return `hsl(${h%360} 55% 36%)`}
function currentHat(){if(S.draft&&S.draft.signed)return{label:initials(S.draft.team),color:hashColor(S.draft.team)};if(S.committed)return{label:initials(S.committed),color:hashColor(S.committed)};return{label:initials(S.team),color:'#173d58'}}
function avatarSVG(size=88){let h=currentHat(),a=S.avatar||{skin:'#b97850',hair:'#21160f',style:'Short'};return `<svg viewBox="0 0 100 100" width="${size}" height="${size}" aria-label="Player avatar"><rect width="100" height="100" fill="#0a1b23"/><path d="M18 100 Q23 70 50 68 Q77 70 82 100" fill="${h.color}"/><circle cx="50" cy="45" r="25" fill="${a.skin}"/><path d="M27 42 Q29 14 50 15 Q74 16 74 43 Q63 28 29 39" fill="${a.hair}"/><circle cx="41" cy="47" r="2"/><circle cx="59" cy="47" r="2"/><path d="M42 58 Q50 63 58 58" fill="none" stroke="#532d25" stroke-width="2" stroke-linecap="round"/><path d="M22 29 Q50 10 79 30 L76 39 Q49 28 25 40Z" fill="${h.color}"/><path d="M72 34 Q88 36 91 42 Q76 43 63 39" fill="${h.color}"/><text x="50" y="32" fill="white" text-anchor="middle" font-size="11" font-weight="900">${h.label}</text></svg>`}
function attrCost(v){if(v<55)return 2;if(v<65)return 3;if(v<75)return 4;if(v<85)return 6;if(v<95)return 9;return 14}
function careerGoal(){if(S.path!=='High School')return S.path==='College'?'Win the College World Series and improve your draft stock.':S.path==='JUCO'?'Earn a transfer or another draft opportunity.':'Reach the Major Leagues.';if(S.year==='Senior')return S.combineInvite?'Win a state title and prepare for the Draft Combine.':'Win a state title and earn a Draft Combine invitation.';return 'Develop into a top recruit and chase a state championship.'}
function addMilestone(key,title,detail){if(S.milestones.some(x=>x.key===key))return false;let m={key,title,detail,year:S.year,week:S.week,time:Date.now()};S.milestones.unshift(m);S.news.unshift(`🏆 ${title}${detail?' — '+detail:''}`);return true}
function checkMilestones(){let c=S.careerStats||S.stats;if(c.h>=1)addMilestone('first-hit','First Varsity Hit',`${S.year} year`);if(c.hr>=1)addMilestone('first-hr','First Varsity Home Run',`${S.year} year`);[10,25,50,100,150,200].forEach(n=>{if(c.h>=n)addMilestone(`hit-${n}`,`${n} Career Hits`,`${S.team}`)});[10,25,50].forEach(n=>{if(c.hr>=n)addMilestone(`hr-${n}`,`${n} Career Home Runs`,`${S.team}`)});if(S.world.colleges.some(c=>c.scholarship))addMilestone('first-offer','First Division I Offer',S.world.colleges.find(c=>c.scholarship)?.name||'');if(S.showcases.length)addMilestone('first-showcase','First Showcase Invitation',S.showcases[0].name);if(S.combineInvite)addMilestone('combine','MLB Draft Combine Invitation','One of the top players in the class')}
