  positionKinds(){if(S.position==='Two-Way')return['bat','field','run','pitch'];if(['SP','RP','CP'].includes(S.position))return['pitch','field'];return['bat','field','run']},
  pickTemplate(g){let s=g.state,kinds=this.positionKinds(),pool=this.templates.filter(t=>(!t.positions||t.positions.includes(S.position)||(S.position==='Two-Way'&&(!t.positions||t.positions.includes('SS')||t.positions.includes('P'))))&&kinds.includes(t.type)&&t.eligible(g,s));if(!pool.length)pool=this.templates.filter(t=>kinds.includes(t.type)&&(!t.positions||t.positions.includes(S.position)));let high=this.leverage(s,g)>=5||g.big;if(high){let leveraged=pool.filter(t=>['ss_walkoff_home','of_tag','bat_runner3','run_tag','pitch_runner3','corner_loaded'].includes(t.id));if(leveraged.length)pool=leveraged}let t=pick(pool),m=t.setup(g,s);m.id=t.id;m.type=t.type;m.leverage=this.leverage(s,g);return m},
